using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer uses DateTime.UtcNow
        // (non-deterministic seed values cause spurious migrations).
        // Use a fixed value instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---

class CosmosDbContext : DbContext
{
    public DbSet<Vehicle> Vehicles => Set<Vehicle>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=fake",
            "VehicleDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // BREAKING CHANGE 1: EF Core 9 Cosmos provider now uses "$type" instead of
        // "Discriminator" by default. For existing documents that already store
        // "Discriminator", you must explicitly configure the property name.
        modelBuilder.Entity<Vehicle>()
            .HasDiscriminator<string>("Discriminator");

        modelBuilder.Entity<Vehicle>()
            .ToContainer("Vehicles")
            .HasPartitionKey(v => v.PartitionKey);
    }
}

abstract class Vehicle
{
    public string Id { get; set; } = default!;
    public string PartitionKey { get; set; } = default!;
}
class Car : Vehicle { public int Seats { get; set; } }
class Truck : Vehicle { public double PayloadTons { get; set; } }

// --- Cosmos query service demonstrating sync → async migration ---

class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BREAKING CHANGE 2: EF Core 9 Cosmos provider removed synchronous query
    // support. All queries must use async (ToListAsync, FirstOrDefaultAsync, etc.).
    // Before (would throw InvalidOperationException in EF Core 9):
    //   var cars = _db.Vehicles.OfType<Car>().ToList();
    // After:
    public async Task<List<Car>> GetCarsAsync()
        => await _db.Vehicles.OfType<Car>().ToListAsync();

    public async Task<Vehicle?> GetVehicleAsync(string id)
        => await _db.Vehicles.FirstOrDefaultAsync(v => v.Id == id);
}

